import pandas as pd


def solve(data):
    ban = pd.read_csv('coffee-sales-cc0.csv')
    tong = float(ban['money'].sum())
    nhom = ban.groupby(data['cot'])['money'].sum()
    return {'so_nhom': int(nhom.size),
            'nhom_lon_nhat': str(nhom.idxmax()),
            'lech': round(abs(float(nhom.sum()) - tong), 6)}
